 * Format a key fingerprint
 *
 * @param {string} fingerprint  - Unformatted OpenPGP fingerprint.
 * @returns {string} The formatted string.
 */
formatFpr(fingerprint) {
  let r = "";
  const fpr = fingerprint.match(
    /(....)(....)(....)(....)(....)(....)(....)(....)(....)?(....)?/
  );
  if (fpr && fpr.length > 2) {
    fpr.shift();
    r = fpr.join(" ");
  }

  return r;
},

